export default async function list({ previous, query }, ctx) {
  const s = previous ?? { cursor: null, threads: [] },
    args = { query, maxResults: 100, verbose: false };
  if (s.cursor) args.pageToken = s.cursor;
  const r = await ctx.actions.call("gmail.list_threads", args);
  if (!Array.isArray(r?.threads) || !Object.hasOwn(r, "nextPageToken"))
    throw Error("Invalid Gmail thread list");
  return {
    state: { cursor: r.nextPageToken ?? null, threads: s.threads.concat(r.threads) },
    more: !!r.nextPageToken,
  };
}

