export default function next({ threads, previous }) {
  const index = previous?.index ?? 0,
    t = threads[index];
  if (t && !t.threadId) throw Error("Missing thread ID");
  return { state: { index: index + (t ? 1 : 0) }, more: !!t, threadId: t?.threadId ?? "" };
}

