export default function select({ threadId, messages }) {
  const m = messages.at(-1);
  if (!m || m.threadId !== threadId || !m.messageId || !m.sender)
    throw Error("Missing latest message or sender");
  return {
    id: m.messageId,
    threadId,
    to: m.sender,
    subject: m.subject ?? "",
    body: m.messageText ?? "",
  };
}

