export default async function progress({ threadId, id, acknowledge, resolution }, ctx) {
  const key = "gmail-thread-draft:" + threadId + ":" + id;
  let s = await ctx.state.get(key);
  if (s?.status?.startsWith("pending-")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending action " + key);
    if (s.status === "pending-draft") s = resolution === "confirmed" ? { status: "drafted" } : null;
    else s = resolution === "confirmed" ? { status: "done" } : { status: "drafted" };
    await ctx.state.set(key, s);
  }
  return { key, work: s?.status !== "done", draft: !s };
}

