export default function ({ text }) {
  if (!text.trim()) throw Error("Empty draft");
  return {
    html: text
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll("\n", "<br>"),
  };
}

