export default async function confirm({ key, stage, draftId, threadId, expected }, ctx) {
  if (stage === "draft" && (!draftId || (threadId && threadId !== expected)))
    throw Error("Unknown draft result");
  if (stage === "label" && threadId !== expected) throw Error("Unknown label update");
  await ctx.state.set(key, { status: stage === "draft" ? "drafted" : "done" });
  return { ok: true };
}

